// Package original, licensed image bytes without resizing or modifying pixels.
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
const root = fileURLToPath(new URL("../", import.meta.url));
const kinds = [
  "asphalt",
  "concrete",
  "plaster",
  "soil",
  "wood",
  "tiles",
  "cloth",
];
let source =
  "// Generated by scripts/pack-photo-assets.mjs from the original assets.\n";
source +=
  "// See ATTRIBUTIONS.md and assets/photo-manifest.json for CC0 provenance.\n";
source += "export const PHOTO_DATA = {\n";
for (const kind of kinds) {
  source += JSON.stringify(kind) + ":{";
  for (const [key, channel] of [
    ["map", "albedo"],
    ["normalMap", "normal"],
    ["roughnessMap", "roughness"],
  ]) {
    const bytes = await readFile(
      root + "assets/" + kind + "-" + channel + ".jpg",
    );
    source +=
      JSON.stringify(key) +
      ":" +
      JSON.stringify("data:image/jpeg;base64," + bytes.toString("base64")) +
      ",";
  }
  source += "},\n";
}
source += "};\n";
const hdr = await readFile(root + "assets/rooitou-park-1k.hdr");
source +=
  "export const HDR_BASE64=" + JSON.stringify(hdr.toString("base64")) + ";\n";
await writeFile(root + "src/photo-assets-data.js", source);
console.log(
  "Packed " +
    kinds.length +
    " original PBR sets and HDRI (" +
    Math.round(source.length / 1024) +
    " KB JS).",
);
